#!/usr/bin/env bash
# Generated by mined_to_harbor. Verifier for one mined tier-2 task. Do not edit.
set -u
V=/logs/verifier
mkdir -p "$V"
step() { printf '{"step":"%s","rc":%s%s}\n' "$1" "$2" "${3:-}" | tee -a "$V/steps.jsonl"; }
cd /app
timeout 900 /bin/sh /opt/talos-task/agent-gate.sh > "$V/agent-gate-post.out" 2>&1; step agent_gate_post "$?"
git -C /app status --porcelain -uall > "$V/porcelain.txt" 2> "$V/porcelain.err"; step porcelain "$?"
python3 -I -c 'import json, sys; sys.path.insert(0, "/tests"); import mined_score; a, m = mined_score.parse_authored_tests(sys.stdin.read()); print(json.dumps({"added": a, "modified": m}))' < "$V/porcelain.txt" > "$V/authored.json"; step authored "$?"
printf '{"head":"%s","baseline":"%s","commits_ahead":%s}\n' "$(git -C /app rev-parse HEAD 2>/dev/null || echo unknown)" "$(git -C /app rev-parse talos-baseline 2>/dev/null || echo unknown)" "$(git -C /app rev-list --count talos-baseline..HEAD 2>/dev/null || echo null)" > "$V/verify-meta.json"
cp -a /tests/sealed/. /app/; rc=$?; step sealed_copy "$rc"; [ "$rc" -eq 0 ] || exit 1
(cd /tests/sealed && find . -type f -print0 | while IFS= read -r -d '' f; do cmp -s "$f" "/app/$f" || { echo "sealed mismatch: $f"; exit 1; }; done) > "$V/sealed-check.txt" 2>&1; rc=$?; step sealed_check "$rc"; [ "$rc" -eq 0 ] || exit 1
GATE=$(python3 -I -c 'import json; print(json.load(open("/tests/task_score.json"))["gate_command"])'); rc=$?; step gate_cmd "$rc"; { [ "$rc" -eq 0 ] && [ -n "$GATE" ]; } || exit 1
t0=$(date +%s%3N)
PYTEST_ADDOPTS=-rA timeout 180 bash -c "$GATE" > "$V/gate.out" 2> "$V/gate.err"; rc=$?
step gate "$rc" ",\"gate_ms\":$(( $(date +%s%3N) - t0 ))"
python3 /tests/mined_score.py --task /tests/task_score.json --gate-output "$V/gate.out" --gate-stderr "$V/gate.err" --gate-exit-code "$rc" --authored "$V/authored.json" --out-dir "$V"; step score "$?"
